const item = $input.first().json.body || $input.first().json;

// TRAVA ANTI-LOOP: ignora se não for um pedido novo oficial da rifa
if (item.event !== 'order_created' || !item.orderId) {
  return [];
}

const totalFormatted = Number(item.totalAmount || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const cotas = Array.isArray(item.selectedNumbers) ? item.selectedNumbers.join(', ') : item.selectedNumbers;

const messageText = `🔔 *NOVO PEDIDO NA RIFA BENEFICENTE!*\n\n` +
  `👤 *Comprador:* ${item.customerName}\n` +
  `📱 *WhatsApp:* ${item.customerPhone}\n` +
  `🎫 *Cotas (${item.numbersCount}):* ${cotas}\n` +
  `💰 *Valor a conferir:* R$ ${totalFormatted}\n\n` +
  `🔑 *Chave PIX da Alane:* ${item.pixKey}\n\n` +
  `Confira no app do seu banco se o PIX caiu.\n\n` +
  `✅ *CLIQUE ABAIXO PARA APROVAR:*\n` +
  `👉 ${item.approveUrl}\n\n` +
  `❌ *Para cancelar:*\n` +
  `👉 ${item.cancelUrl}`;

return [{
  json: {
    ...item,
    totalFormatted,
    cotas,
    messageText,
    adminPhone: '556392917027'
  }
}];

